import { Contact } from "@/registry/bases/base/blocks/contact-01/components/contact-01"
import { dictionary } from "@/registry/bases/base/blocks/contact-01/contact-01-dictionary"

export default async function Page({
  params,
}: {
  params?: Promise<{ lang?: string }>
}) {
  const { lang } = (await params) ?? {}
  const locale = lang === "ar" ? "ar" : "en"
  return <Contact dictionary={dictionary[locale]} lang={locale} />
}

import {
  ArrowUpRight,
  Clock,
  Mail,
  MapPin,
  MessageCircle,
  Phone,
  type LucideIcon,
} from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  ContactForm,
  type ContactFormDictionary,
} from "@/registry/bases/base/blocks/contact-01/components/contact-01-form"

const icons = {
  chat: MessageCircle,
  phone: Phone,
  email: Mail,
  location: MapPin,
  hours: Clock,
} satisfies Record<string, LucideIcon>

export type ContactDictionary = {
  eyebrow?: string
  title: string
  lead: string
  channels: {
    title: string
    items: {
      icon: keyof typeof icons
      title: string
      body?: string
      /** Primary contact value, e.g. a phone number or email address. */
      value?: { label: string; href: string; ltr?: boolean }
      /** Multi-line postal address. */
      address?: string[]
      action?: { label: string; href: string }
      highlight?: boolean
    }[]
  }
  message: {
    title: string
    lead: string
    privacy: string
    form: ContactFormDictionary
  }
}

export function Contact({
  dictionary,
  lang,
  className,
}: {
  dictionary: ContactDictionary
  lang: "en" | "ar"
  className?: string
}) {
  const dir = lang === "ar" ? "rtl" : "ltr"
  const { channels, message } = dictionary

  return (
    <section
      dir={dir}
      aria-labelledby="contact-title"
      className={cn("bg-background py-16 md:py-24", className)}
    >
      <div className="mx-auto flex max-w-6xl flex-col gap-16 px-6 md:gap-24">
        <div className="flex flex-col gap-10">
          <div className="max-w-2xl">
            {dictionary.eyebrow && (
              <p className="mb-3 text-sm font-medium text-primary">
                {dictionary.eyebrow}
              </p>
            )}
            <h2
              id="contact-title"
              className="font-heading text-3xl font-bold tracking-tight text-balance md:text-5xl"
            >
              {dictionary.title}
            </h2>
            <p className="mt-4 text-lg text-pretty text-muted-foreground">
              {dictionary.lead}
            </p>
          </div>

          <div className="flex flex-col gap-6">
            <h3 className="font-heading text-xl font-semibold tracking-tight">
              {channels.title}
            </h3>
            <ul className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
              {channels.items.map((item) => {
                const Icon = icons[item.icon]
                return (
                  <li
                    key={item.title}
                    className={cn(
                      "flex flex-col items-start gap-4 rounded-3xl p-6",
                      item.highlight
                        ? "bg-primary/5 ring-1 ring-primary/15 dark:bg-primary/10"
                        : "border bg-background"
                    )}
                  >
                    <span
                      aria-hidden="true"
                      className="grid size-11 place-items-center rounded-full bg-foreground text-background [&_svg]:size-5"
                    >
                      <Icon />
                    </span>
                    <div className="flex flex-col gap-1">
                      <h4 className="text-lg font-semibold tracking-tight">
                        {item.title}
                      </h4>
                      {item.body && (
                        <p className="text-pretty text-muted-foreground">
                          {item.body}
                        </p>
                      )}
                    </div>
                    {item.value && (
                      <a
                        href={item.value.href}
                        dir={item.value.ltr ? "ltr" : undefined}
                        className="inline-flex min-h-11 items-center rounded-sm text-lg font-medium break-all tabular-nums underline-offset-4 outline-none hover:underline focus-visible:ring-3 focus-visible:ring-ring/50"
                      >
                        {item.value.label}
                      </a>
                    )}
                    {item.address && (
                      <address className="font-medium not-italic">
                        {item.address.map((line) => (
                          <span key={line} className="block">
                            {line}
                          </span>
                        ))}
                      </address>
                    )}
                    {item.action && (
                      <Button
                        variant={item.highlight ? "default" : "outline"}
                        size="sm"
                        className="mt-auto px-3"
                        nativeButton={false}
                        render={<a href={item.action.href} />}
                      >
                        {item.action.label}
                        <ArrowUpRight
                          aria-hidden="true"
                          className="rtl:-scale-x-100"
                        />
                      </Button>
                    )}
                  </li>
                )
              })}
            </ul>
          </div>
        </div>

        <div className="grid gap-10 lg:grid-cols-[1fr_1.4fr] lg:gap-20">
          <div className="flex flex-col gap-4">
            <h3 className="font-heading text-2xl font-bold tracking-tight text-balance md:text-3xl">
              {message.title}
            </h3>
            <p className="text-lg text-pretty text-muted-foreground">
              {message.lead}
            </p>
            <p className="text-sm text-muted-foreground">{message.privacy}</p>
          </div>
          <ContactForm dictionary={message.form} />
        </div>
      </div>
    </section>
  )
}

"use client"

import * as React from "react"
import { CheckCircle2, Send } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"

export type ContactFormDictionary = {
  name: { label: string; placeholder: string }
  email: { label: string; placeholder: string }
  phone: { label: string; placeholder: string }
  message: { label: string; placeholder: string }
  submit: string
  success: { title: string; description: string; again: string }
}

export function ContactForm({
  dictionary,
  className,
}: {
  dictionary: ContactFormDictionary
  className?: string
}) {
  const id = React.useId()
  const [sent, setSent] = React.useState(false)

  if (sent) {
    return (
      <div
        role="status"
        className={cn(
          "flex flex-col items-start gap-4 rounded-3xl border bg-card p-6 text-card-foreground sm:p-8",
          className
        )}
      >
        <CheckCircle2 aria-hidden="true" className="size-8 text-primary" />
        <div className="flex flex-col gap-1">
          <p className="text-lg font-semibold">{dictionary.success.title}</p>
          <p className="text-muted-foreground">
            {dictionary.success.description}
          </p>
        </div>
        <Button variant="outline" onClick={() => setSent(false)}>
          {dictionary.success.again}
        </Button>
      </div>
    )
  }

  return (
    <form
      onSubmit={(event) => {
        // Demo only: wire your own server action or API route here.
        event.preventDefault()
        setSent(true)
      }}
      className={cn(
        "rounded-3xl border bg-card p-6 text-card-foreground sm:p-8",
        className
      )}
    >
      <FieldGroup className="gap-5">
        <div className="grid gap-5 sm:grid-cols-2">
          <Field>
            <FieldLabel htmlFor={`${id}-name`}>{dictionary.name.label}</FieldLabel>
            <Input
              id={`${id}-name`}
              name="name"
              autoComplete="name"
              placeholder={dictionary.name.placeholder}
              required
            />
          </Field>
          <Field>
            <FieldLabel htmlFor={`${id}-email`}>
              {dictionary.email.label}
            </FieldLabel>
            <Input
              id={`${id}-email`}
              name="email"
              type="email"
              autoComplete="email"
              dir="ltr"
              placeholder={dictionary.email.placeholder}
              className="text-start rtl:text-end"
              required
            />
          </Field>
        </div>
        <Field>
          <FieldLabel htmlFor={`${id}-phone`}>{dictionary.phone.label}</FieldLabel>
          <Input
            id={`${id}-phone`}
            name="phone"
            type="tel"
            autoComplete="tel"
            dir="ltr"
            placeholder={dictionary.phone.placeholder}
            className="text-start rtl:text-end"
          />
        </Field>
        <Field>
          <FieldLabel htmlFor={`${id}-message`}>
            {dictionary.message.label}
          </FieldLabel>
          <Textarea
            id={`${id}-message`}
            name="message"
            rows={5}
            placeholder={dictionary.message.placeholder}
            className="min-h-32"
            required
          />
        </Field>
        <Button type="submit" size="lg" className="w-full px-5 sm:w-fit">
          {dictionary.submit}
          <Send aria-hidden="true" className="rtl:-scale-x-100" />
        </Button>
      </FieldGroup>
    </form>
  )
}

